  /** IPv6 interface addresses (CIDR); L3 tunnels only. */
  ipv6: string[];
  /** Bridge domain id (L2 tunnels: teb, erspan). */
  bridgeDomain?:
    | number
    | undefined;
  /** Destination address. */
  dst?:
    | string
    | undefined;
  /** "l3" | "teb" | "erspan". */
