/** AclRule mirrors one entry of `acl.lists.<name>.rules`. */
export interface AclRule {
  /** Sequence number 1..2^31-1, unique within the list; rules are evaluated in this order. */
  sequence?:
    | number
    | undefined;
  /** Free-text description. */
  description?:
    | string
    | undefined;
  /** Rule enabled. */
  enabled?:
    | boolean
    | undefined;
  /** "permit" | "deny" | "reflect". */
  action?:
    | string
    | undefined;
  /** "ipv4" | "ipv6" | "any". */
  ipVersion?:
    | string
    | undefined;
  /** Source match; unset = any. */
  source:
    | AddressMatch
    | undefined;
  /** Destination match; unset = any. */
  destination:
    | AddressMatch
    | undefined;
  /** Service match; unset = any. */
  service:
    | ServiceMatch
    | undefined;
  /** Name from objects.schedules; unset = always. */
  schedule?:
    | string
    | undefined;
  /** Log matches. */
  log?:
    | boolean
    | undefined;
  /** F-rule-expiry: RFC 3339 with offset; at that instant the agent stops rendering the rule (no commit). Unset = never. */
  expiresAt?:
    | string
    | undefined;
  /** F-rule-expiry: who asked for the rule (metadata only). */
  owner?:
    | string
    | undefined;
  /** F-rule-expiry: change/ticket reference (metadata only). */
  ticket?: string | undefined;
}

